items.css:
.ql-method-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(240px, 1fr)); gap: clamp(calc(28px * var(--vb-s)), 3.5vw, calc(44px * var(--vb-s))); }
.ql-method-card { text-align: center; }
.ql-method-card__img { width: 100%; height: auto; display: block; border-radius: 16px; border: 1px solid var(--vb-line); }
.ql-method-card__body { padding: 16px 6px 0px; }
.ql-method-card__tag { display: block; font-size: 0.72rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; color: var(--accent-color); margin-bottom: 8px; }
.ql-method-card__title { margin: 0px 0px 6px; font-size: var(--fs-body); font-weight: 700; color: var(--vb-text); word-break: keep-all; }
.ql-method-card__desc { margin: 0px; font-size: var(--fs-caption); line-height: 1.65; color: var(--vb-muted); word-break: keep-all; }
.reveal { opacity: 0; transform: translateY(40px); will-change: opacity, transform; }
@media (max-width: 768px) {
    img { max-width: 100%; }
}
